import type { OccurrenceRef } from './contracts';

/** An explicit focus is required. A focus containing several numbers is not atomic. */
export function occurrenceKey(fieldId: string, occurrence: OccurrenceRef): string | undefined {
  const focus = occurrence.focusSpan;
  if (!focus || (focus.text.match(/\d[\d.,]*/g) ?? []).length > 1) return undefined;
  return JSON.stringify([occurrence.messageId, fieldId, focus.start, focus.end]);
}
import { z } from 'zod';
import { EvidenceRefSchema, FactValueSchema, InterpretationSchema, SubjectRefSchema } from '../../../contracts';

const id = z.string().min(1);
export const SpanSchema = z.strictObject({ start: z.number().int().nonnegative(), end: z.number().int().nonnegative(), text: z.string().min(1) }).refine(s => s.end > s.start);
export const OccurrenceRefSchema = z.strictObject({ messageId: id, statementSpan: SpanSchema, focusSpan: SpanSchema.optional(), previousAssertionId: id.optional() });
export const RawClaimSchema = z.strictObject({ fieldId: id, subjectRef: SubjectRefSchema, value: FactValueSchema.optional(), unit: id.optional(), period: id.optional(), incomeBasis: z.enum(['net', 'gross', 'unknown']).optional(), precision: z.enum(['explicit', 'approximate', 'ambiguous', 'inferred']), occurrence: OccurrenceRefSchema, evidenceRefs: z.array(EvidenceRefSchema).min(1), correction: z.boolean().optional() });
export const ClaimCandidateSchema = RawClaimSchema.extend({ candidateId: id, extractorId: id });
export const ClaimGroupSchema = z.strictObject({ groupId: id, occurrence: OccurrenceRefSchema, fieldId: id, candidates: z.array(ClaimCandidateSchema).min(1) });
export const DisputeSchema = z.strictObject({ disputeId: id, groupId: id, candidateIds: z.array(id).min(1), reason: id });
export const ResolutionSchema = z.discriminatedUnion('status', [z.strictObject({ status: z.literal('selected'), candidateId: id, justification: id }), z.strictObject({ status: z.literal('unresolved'), justification: id })]);
export const AdjudicationResponseSchema = z.strictObject({ disputeId: id, resolution: ResolutionSchema });
export const ReconciliationResultSchema = z.strictObject({ interpretation: InterpretationSchema, disputes: z.array(DisputeSchema), resolutions: z.array(AdjudicationResponseSchema) });
export type OccurrenceRef = z.infer<typeof OccurrenceRefSchema>;
export type RawClaim = z.infer<typeof RawClaimSchema>;
export type ClaimCandidate = z.infer<typeof ClaimCandidateSchema>;
export type ClaimGroup = z.infer<typeof ClaimGroupSchema>;
import type { Message } from '../../../contracts';
import { OccurrenceRefSchema, type OccurrenceRef } from './contracts';

export function validateOccurrence(value: OccurrenceRef, messages: Message[]): boolean {
  const parsed = OccurrenceRefSchema.safeParse(value);
  if (!parsed.success) return false;
  const { messageId, statementSpan: statement, focusSpan: focus } = parsed.data;
  const matches = messages.filter(m => m.messageId === messageId);
  if (matches.length !== 1) return false;
  const message = matches[0];
  if (message.role !== 'customer' || message.content.type !== 'text') return false;
  const text = message.content.text;
  const valid = (span: typeof statement) => span.end <= text.length && text.slice(span.start, span.end) === span.text;
  return valid(statement) && (!focus || (focus.start >= statement.start && focus.end <= statement.end && valid(focus)));
}

import type { FactSchema } from '../../../contracts';
import { ClaimCandidateSchema, type ClaimCandidate } from './contracts';

export function validateCandidate(candidate: ClaimCandidate, schema: FactSchema, messages: Message[]): boolean {
  const parsed = ClaimCandidateSchema.safeParse(candidate);
  if (!parsed.success || !validateOccurrence(candidate.occurrence, messages)) return false;
  const field = schema.fields.find(f => f.id === candidate.fieldId);
  if (!field || !field.scopes.includes(candidate.subjectRef.scope) || (candidate.unit !== undefined && !field.units.includes(candidate.unit))) return false;
  const value = candidate.value;
  if (value === undefined && candidate.precision !== 'ambiguous' && !candidate.correction) return false;
  if (value !== undefined) {
    const range = typeof value === 'object' && !Array.isArray(value);
    const valid = field.type === 'money' || field.type === 'range' ? typeof value === 'number' || range : field.type === 'number' ? typeof value === 'number' : field.type === 'boolean' ? typeof value === 'boolean' : field.type === 'collection' ? Array.isArray(value) : typeof value === 'string';
    if (!valid || (field.type === 'enum' && (typeof value !== 'string' || !field.enumOptions.includes(value)))) return false;
    const numbers = typeof value === 'number' ? [value] : range ? [value.min, value.max] : [];
    const constraints = field.structuralValidation;
    if (numbers.some(n => (constraints?.min !== undefined && n < constraints.min) || (constraints?.max !== undefined && n > constraints.max) || (constraints?.integer && !Number.isInteger(n)))) return false;
  }
  return validateEvidenceRefs(candidate, messages);
}

export function validateEvidenceRefs(candidate: ClaimCandidate, messages: Message[]): boolean {
  return candidate.evidenceRefs.every(ref => {
    const matching = messages.filter(m => m.messageId === ref.messageId);
    if (matching.length !== 1 || ref.messageId !== candidate.occurrence.messageId) return false;
    const m = matching[0];
    if (m.role !== 'customer' || m.content.type !== 'text') return false;
    if (ref.start !== undefined && ref.end !== undefined) return ref.end <= m.content.text.length && (!ref.quote || m.content.text.slice(ref.start, ref.end) === ref.quote);
    return !ref.quote || m.content.text.includes(ref.quote);
  });
}
import type { Message } from '../../../contracts';
import { ClaimCandidateSchema, type ClaimCandidate, type ClaimGroup } from './contracts';
import { validateEvidenceRefs, validateOccurrence } from './evidence';
import { occurrenceKey } from './alignment';

export function groupClaims(candidates: ClaimCandidate[], messages: Message[]): { groups: ClaimGroup[]; rejected: ClaimCandidate[] } {
  const groups = new Map<string, ClaimGroup>();
  const rejected: ClaimCandidate[] = [];
  const ids = new Set<string>();
  for (const candidate of candidates) {
    const parsed = ClaimCandidateSchema.safeParse(candidate);
    if (!parsed.success || !validateOccurrence(candidate.occurrence, messages) || !validateEvidenceRefs(candidate, messages) || ids.has(candidate.candidateId)) { rejected.push(candidate); continue; }
    const key = occurrenceKey(candidate.fieldId, candidate.occurrence);
    if (!key) { rejected.push(candidate); continue; }
    const group = groups.get(key);
    if (group?.candidates.some(c => c.extractorId === candidate.extractorId)) { rejected.push(candidate); continue; }
    ids.add(candidate.candidateId);
    if (group) group.candidates.push(candidate);
    else groups.set(key, { groupId: key, fieldId: candidate.fieldId, occurrence: candidate.occurrence, candidates: [candidate] });
  }
  return { groups: [...groups.values()], rejected };
}
